# %% [markdown] id="42DUHkQzBW53" papermill={"duration": 0.041461, "end_time": "2020-11-23T18:37:05.789118", "exception": false, "start_time": "2020-11-23T18:37:05.747657", "status": "completed"}
# #### Computing RMSE and R^2 Values
# RMSE is the standard deviation of the errors which occur when a prediction is made on a dataset. This is the same as MSE (Mean Squared Error) but the root of the value is considered while determining the accuracy of the model
#

# %% colab={"base_uri": "https://localhost:8080/"} id="eVZMm1zxlQlE" executionInfo={"status": "ok", "timestamp": 1723969626528, "user_tz": -180, "elapsed": 9, "user": {"displayName": "Ahmed Yousry", "userId": "15736517196575255940"}} outputId="f24cc3f6-49da-4518-903a-4c155d8b5fcd"
# prompt: compute the MSE and RMSE and R square

from sklearn.metrics import mean_squared_error, r2_score
mse = mean_squared_error(y_test, y_pred)
rmse = mean_squared_error(y_test, y_pred, squared=False)
r_squared = r2_score(y_test, y_pred)
print('Mean_Squared_Error :' ,mse)
print('Root_Mean_Squared_Error :' ,rmse)
print('r_square_value :',r_squared)


